package com.secwatch.service;
import com.secwatch.dto.*; import com.secwatch.exception.ApiException; import com.secwatch.model.*; import com.secwatch.repository.*; import com.secwatch.security.JwtService;
import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
import java.time.Instant; import java.util.*;

@Service @Transactional public class AppService {
 public final UserRepository users; final IncidentRepository incidents; final HistoryRepository histories; final CommentRepository comments; final PasswordEncoder encoder; final JwtService jwt;
 public AppService(UserRepository u,IncidentRepository i,HistoryRepository h,CommentRepository c,PasswordEncoder e,JwtService j){users=u;incidents=i;histories=h;comments=c;encoder=e;jwt=j;}
 ApiException err(HttpStatus s,String m){return new ApiException(s,m);} User current(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->err(HttpStatus.NOT_FOUND,"Utilisateur introuvable."));}
 public Views.AuthView register(Requests.Register r){if(users.existsByEmailIgnoreCase(r.email()))throw err(HttpStatus.CONFLICT,"Cette adresse email est déjà utilisée.");User u=new User();u.fullName=r.fullName().trim();u.email=r.email().trim().toLowerCase();u.password=encoder.encode(r.password());u.role=Role.EMPLOYEE;users.save(u);return auth(u);}
 public Views.AuthView login(Requests.Login r){User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->err(HttpStatus.UNAUTHORIZED,"Email ou mot de passe incorrect."));if(!u.enabled||!encoder.matches(r.password(),u.password))throw err(HttpStatus.UNAUTHORIZED,"Email ou mot de passe incorrect.");return auth(u);}
 Views.AuthView auth(User u){return new Views.AuthView(jwt.generate(u),u.role,u.fullName,Views.UserView.of(u),jwt.ttl());}
 public Views.UserView profile(String email){return Views.UserView.of(current(email));}
 public Views.UserView updateProfile(String email,Requests.Profile r){User u=current(email);if(!u.email.equalsIgnoreCase(r.email())&&users.existsByEmailIgnoreCase(r.email()))throw err(HttpStatus.CONFLICT,"Cette adresse email est déjà utilisée.");u.email=r.email().trim().toLowerCase();u.fullName=r.fullName().trim();return Views.UserView.of(u);}
 public void password(String email,Requests.Password r){User u=current(email);if(!encoder.matches(r.oldPassword(),u.password))throw err(HttpStatus.BAD_REQUEST,"Ancien mot de passe incorrect.");if(!r.newPassword().equals(r.confirmation()))throw err(HttpStatus.BAD_REQUEST,"La confirmation ne correspond pas.");u.password=encoder.encode(r.newPassword());u.tokenVersion++;}
 Incident get(Long id){return incidents.findWithUsersById(id).orElseThrow(()->err(HttpStatus.NOT_FOUND,"Incident introuvable."));}
 void history(Incident i,User actor,String m){IncidentHistory h=new IncidentHistory();h.incident=i;h.actor=actor;h.message=m;histories.save(h);}
 public Views.IncidentView create(String email,Requests.NewIncident r){User u=current(email);Incident i=new Incident();i.title=r.title().trim();i.description=r.description().trim();i.category=r.category();i.priority=r.priority();i.createdBy=u;i.status=Status.OPEN;incidents.save(i);history(i,u,"Incident créé.");return Views.IncidentView.of(i);}
 boolean sameUser(User left,User right){return left!=null&&right!=null&&left.getId()!=null&&right.getId()!=null&&left.getId().equals(right.getId());}
 boolean canSee(Incident i,User u){return u.role==Role.ADMIN||sameUser(i.createdBy,u)||(u.role==Role.TECHNICIAN&&sameUser(i.assignedTo,u));}
 public Views.Detail detail(String email,Long id){User u=current(email);Incident i=get(id);if(!canSee(i,u))throw err(HttpStatus.FORBIDDEN,"Vous ne pouvez pas consulter cet incident.");return new Views.Detail(Views.IncidentView.of(i),histories.findByIncidentIdOrderByCreatedAtAscIdAsc(id).stream().map(Views.HistoryView::of).toList(),comments.findByIncidentIdOrderByCreatedAtAscIdAsc(id).stream().map(Views.CommentView::of).toList());}
 public List<Views.IncidentView> mine(String e){return incidents.findByCreatedByIdOrderByCreatedAtDesc(current(e).id).stream().map(Views.IncidentView::of).toList();}
 public List<Views.IncidentView> assigned(String e){return incidents.findByAssignedToIdOrderByCreatedAtDesc(current(e).id).stream().map(Views.IncidentView::of).toList();}
 List<Incident> allIncidentRows(){var rows=incidents.findAll();rows.sort((a,b)->b.createdAt.compareTo(a.createdAt));return rows;}
 public List<Views.IncidentView> all(){return allIncidentRows().stream().map(Views.IncidentView::of).toList();}
 public Views.IncidentView status(String email,Long id,Status next){User u=current(email);Incident i=get(id);if(u.role==Role.TECHNICIAN&&!sameUser(i.assignedTo,u))throw err(HttpStatus.FORBIDDEN,"Cet incident ne vous est pas affecté.");if(i.status==Status.CLOSED)throw err(HttpStatus.CONFLICT,"Un incident CLOSED ne peut plus être modifié.");Status old=i.status;i.status=next;i.updatedAt=Instant.now();history(i,u,old+" → "+next);return Views.IncidentView.of(i);}
 public Views.IncidentView assign(String email,Long id,Long techId){User actor=current(email);User tech=users.findById(techId).orElseThrow(()->err(HttpStatus.NOT_FOUND,"Technicien introuvable."));if(tech.role!=Role.TECHNICIAN||!tech.enabled)throw err(HttpStatus.BAD_REQUEST,"Le compte choisi n’est pas un technicien actif.");Incident i=get(id);if(i.status==Status.CLOSED)throw err(HttpStatus.CONFLICT,"Un incident CLOSED ne peut plus être modifié.");i.assignedTo=tech;i.status=Status.ASSIGNED;i.updatedAt=Instant.now();history(i,actor,"Incident affecté à "+tech.fullName+".");incidents.saveAndFlush(i);return Views.IncidentView.of(i);}
 public Views.CommentView comment(String email,Long id,Requests.Comment r){User u=current(email);Incident i=get(id);if(u.role==Role.TECHNICIAN&&!sameUser(i.assignedTo,u))throw err(HttpStatus.FORBIDDEN,"Cet incident ne vous est pas affecté.");if(i.status==Status.CLOSED)throw err(HttpStatus.CONFLICT,"Un incident CLOSED ne peut plus recevoir de note.");IncidentComment c=new IncidentComment();c.incident=i;c.author=u;c.content=r.content().trim();comments.save(c);history(i,u,"Note de traitement ajoutée.");return Views.CommentView.of(c);}
 public List<Views.UserView> userList(){return users.findAll().stream().map(Views.UserView::of).toList();}
 public Views.UserView enable(Long id,boolean on){User u=users.findById(id).orElseThrow(()->err(HttpStatus.NOT_FOUND,"Utilisateur introuvable."));u.enabled=on;if(!on)u.tokenVersion++;return Views.UserView.of(u);}
 Map<String,Long> stats(List<Incident> is){var us=users.findAll();Map<String,Long> m=new LinkedHashMap<>();m.put("totalUsers",(long)us.size());m.put("employees",us.stream().filter(u->u.role==Role.EMPLOYEE).count());m.put("technicians",us.stream().filter(u->u.role==Role.TECHNICIAN).count());m.put("totalIncidents",(long)is.size());for(Status s:Status.values())m.put(s.name().toLowerCase(),is.stream().filter(i->i.status==s).count());m.put("critical",is.stream().filter(i->i.priority==Priority.CRITICAL).count());return m;}
 public Map<String,Long> stats(){return stats(incidents.findAll());}
 public Views.AdminDashboard adminDashboard(){var rows=allIncidentRows();return new Views.AdminDashboard(stats(rows),rows.stream().map(Views.IncidentView::of).toList());}
}
